export const APP_ID = 'budget';
// Legacy identifiers exist only to recover data from previous versions.
export const LEGACY_APP_ID = 'reserva';
export const DATABASE_NAME = APP_ID;
export const LEGACY_DATABASE_NAME = `${LEGACY_APP_ID}-financas`;
export const DEVICE_STORAGE_KEY = `${APP_ID}.drive.deviceId`;
export const LEGACY_DEVICE_STORAGE_KEY = `${LEGACY_APP_ID}.drive.deviceId`;

/** Keeps import identities compatible with account labels generated by earlier releases. */
export function canonicalAccountIdentity(account: string): string {
  const normalized = account.trim().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ');
  // These Portuguese prefixes are a persisted fingerprint contract, not display labels.
  return normalized
    .replace(/^itau checking account(?=$|[ •])/, 'conta corrente itau')
    .replace(/^itau card(?=$|[ *])/, 'cartao itau');
}
